218:     const controller = new AbortController();
219:     const timeout = setTimeout(() => controller.abort(), 10_000);
220:     const res = await fetch(`${url}/chat/completions`, {
221:       method: 'POST',
222:       headers: {
223:         'Authorization': `Bearer ${key}`,
224:         'Content-Type': 'application/json',
225:       },
226:       body: JSON.stringify({
227:         model: model,
228:         messages: [{ role: 'user', content: 'ping' }],
229:         max_tokens: 1,
230:       }),
231:       signal: controller.signal,
232:     });
233:     clearTimeout(timeout);
234:     if (res.ok) return true;
235:     // 401/403 = invalid key → unavailable
236:     if (res.status === 401 || res.status === 403) return false;
237:     // 4xx (except 429 rate limit) = misconfigured endpoint → unavailable
238:     if (res.status >= 400 && res.status < 500 && res.status !== 429) return false;
239:     // 5xx or other = might be transient, treat as available
240:     return true;
241:   } catch {
