327: async function runQuickCalibration(): Promise<Record<Line, Stage>> {
328:   const altitudes: Partial<Record<Line, Stage>> = {};
329:   const lines: Line[] = ['Cognitive', 'Emotional', 'Moral', 'Intrapersonal', 'Spiritual', 'Somatic', 'Willpower', 'Interpersonal'];
330: 
331:   banner('Quick Calibration');
332:   console.log(`  ${chalk.dim('A brief probe of each developmental line to set your starting altitudes.')}\n`);
333: 
334:   for (const line of lines) {
335:     let stage: Stage = 'Red';
336:     let confidence = 0.5;
337:     let trial: TrialResult;
338: 
339:     if (line === 'Somatic' || line === 'Willpower') {
340:       // ── Hold probe: measure timing accuracy ──
341:       const target = HOLD_TARGETS[line]!;
342:       const targetSec = (target / 1000).toFixed(1);
343: 
344:       console.log(`  ${chalk.bold.cyan(line + ':')} ${chalk.dim('Timing probe')}`);
345:       console.log(`  ${chalk.dim('Press Enter when you think ' + targetSec + ' seconds have passed.')}\n`);
346: 
347:       const startTime = Date.now();
348:       const answer = await clackText({ message: `Press Enter after ~${targetSec}s...`, defaultValue: '' });
349:       if (typeof answer === 'symbol') { altitudes[line] = 'Red'; continue; }
350:       const elapsed = Date.now() - startTime;
351: 
352:       const accuracy = Math.max(0, 1 - Math.abs(elapsed - target) / target);
353: 
354:       let threshold: number;
355:       if (line === 'Somatic') {
356:         // Inverted: lower RT = higher stage (range 200-900)
357:         threshold = 900 - accuracy * 700;
358:       } else {
359:         // Standard: higher = better (range 1-12)
360:         threshold = 1 + accuracy * 11;
361:       }
362: 
363:       stage = thresholdToStage(line, threshold);
364: 
365:       trial = {
366:         taskId: `cal-${line.toLowerCase()}`,
367:         timestamp: Date.now(),
368:         dimensions: { accuracy, response_time: accuracy },
369:         rawResponse: elapsed,
370:         durationMs: elapsed,
371:       };
372: 
373:       confidence = computeConfidence([trial], 0.5);
374: 
375:     } else {
376:       // ── LLM dialogue probe: multiple choice ──
377:       const probe = CALIBRATION_PROMPTS[line];
378:       if (!probe) { altitudes[line] = 'Red'; continue; }
379: 
380:       console.log(`  ${chalk.bold.cyan(line + ':')}`);
381:       console.log(`  ${chalk.dim(probe.prompt)}\n`);
382: 
383:       const choice = await select({
384:         message: `How would you approach this?`,
385:         options: probe.options.map((opt) => ({ value: opt, label: opt })),
386:       });
387: 
388:       if (typeof choice === 'symbol') { altitudes[line] = 'Red'; continue; }
389: 
390:       const choiceIdx = probe.options.indexOf(choice as string);
391:       const idx = choiceIdx >= 0 ? choiceIdx : 0;
392: 
393:       const thresholds = CHOICE_THRESHOLDS[line]!;
394:       const threshold = thresholds[Math.min(idx, 2)];
395: 
396:       stage = thresholdToStage(line, threshold);
397: 
398:       const depthScores = [0.3, 0.6, 0.85];
399:       const coherenceScores = [0.4, 0.7, 0.9];
400: 
401:       trial = {
402:         taskId: `cal-${line.toLowerCase()}`,
403:         timestamp: Date.now(),
404:         dimensions: { depth: depthScores[idx], coherence: coherenceScores[idx] },
405:         rawResponse: idx,
406:         durationMs: 0,
407:       };
408: 
409:       confidence = computeConfidence([trial], 0.5);
410:     }
411: 
412:     altitudes[line] = stage;
413: 
414:     const stageIdx = CAL_STAGES.indexOf(stage as typeof CAL_STAGES[number]);
415:     const color = stageColor(stage);
416:     const bar = '■'.repeat(stageIdx + 1) + '○'.repeat(7 - stageIdx);
417:     console.log(`  ${line.padEnd(14)} ${bar} ${color(stage)} ${chalk.dim('(confidence: ' + confidence.toFixed(2) + ')')}\n`);
418:   }
419: 
420:   console.log(`\n  ${chalk.bold('Calibration complete:')}`);
421:   for (const line of lines) {
422:     const s = altitudes[line] ?? 'Red';
423:     const color = stageColor(s);
424:     console.log(`    ${line.padEnd(14)} ${color(s)}`);
425:   }
426:   console.log('');
427: 
428:   return altitudes as Record<Line, Stage>;
429: }
