526: /** Render an altitude bar chart showing per-line stage progression */
527: function renderAltitudesChart(sig: Significator): void {
528:   const orderedLines: Line[] = ['Cognitive', 'Emotional', 'Moral', 'Intrapersonal', 'Spiritual', 'Somatic', 'Willpower', 'Interpersonal'];
529:   const allStages = ['Infrared', 'Magenta', 'Red', 'Amber', 'Orange', 'Green', 'Turquoise', 'White'] as const;
530:   const stageKeys: readonly string[] = allStages;
531: 
532:   for (const line of orderedLines) {
533:     const current = sig.altitudes[line] ?? 'Red';
534:     const currentIdx = stageKeys.indexOf(current);
535:     const color = stageColor(current);
536: 
537:     // Build a horizontal bar: filled squares up to current stage, empty beyond
538:     const bars = stageKeys.map((s, i) => {
539:       if (i < currentIdx) return chalk.dim('■');  // passed stages
540:       if (i === currentIdx) return color('●'); // current stage
541:       return chalk.dim('○'); // future stages
542:     });
543: 
544:     // Segment label: first 3 stages, current, last 2
545:     const segLabels = stageKeys.map((s, i) => {
546:       if (i === 0 || i === stageKeys.length - 1 || i === currentIdx) {
547:         return i === currentIdx ? color(stageAbbr(s)) : chalk.dim(stageAbbr(s));
548:       }
549:       return '  '; // skip most labels for compactness
550:     });
551: 
552:     // Pad line name to 15 chars for alignment
553:     const paddedLine = line.padEnd(14);
554:     if (!JSON_MODE) {
555:       console.log(`  ${paddedLine} ${bars.join('')} ${chalk.dim(current)}`);
556:     }
557:   }
558: }
