680: // ── AgenticOrchestrator encounter handler (all modalities) ────────────
681: async function runAgenticEncounter(
682:   encounter: ScheduledEncounter,
683:   sig: Significator,
684:   world: WorldState,
685:   history: ConsequenceRecord[],
686:   responsesPool?: number[],
687:   consecutivePasses?: Map<string, number>,
688: ): Promise<{
689:   outcome: import('../src/core/assessments/AgenticOrchestrator.js').OrchestratorResult;
690:   response: PlayerResponse;
691:   narrativeSummary: string;
692: }> {
693:   const [encLine, encStage] = encounter.moduleRef.split(':') as [Line, Stage];
694:   const modRegistry = (globalThis as any).__moduleRegistry as ModuleRegistry | undefined;
695: 
696:   // If --line/--stage/--modality forcing is active, override the encounter
697:   let forcedEncounter = encounter;
698:   if (FORCE_LINE || FORCE_STAGE || FORCE_MODALITY) {
699:     const forcedLine = FORCE_LINE ?? encLine;
700:     const forcedStage = FORCE_STAGE ?? encStage;
701:     const forcedModality = FORCE_MODALITY ?? encounter.modality;
702:     const forcedModule = modRegistry?.get(forcedLine, forcedStage);
703:     if (forcedModule) {
704:       forcedEncounter = {
705:         ...encounter,
706:         moduleRef: `${forcedLine}:${forcedStage}`,
707:         modality: forcedModality,
708:         targetLines: [forcedLine],
709:         stage: forcedStage,
710:       };
711:     }
712:   }
713: 
714:   const uiHandler: AgenticUIHandler = {
715:     askUser: async (params: AskUserQuestionParams): Promise<AskUserQuestionResult> => {
716:       const answers: UserAnswer[] = [];
717: 
718:       for (const q of params.questions) {
719:         if (!JSON_MODE) {
720:           const mod = forcedEncounter.modality;
721:           let modHeader = '';
722: 
723:           switch (mod) {
724:             case 'Deterministic':
725:               modHeader = `${chalk.bold.red('⏳ [TIMED TRIAL] ▬▬▬▬▬▬▬▬▬▬▬▬▬░ (9.5s remaining)')}\n`;
726:               break;
727:             case 'LanguageReflective':
728:               modHeader = `${chalk.bold.blue('🧘 [REFLECTION BEAT] • Tune in to your inner state •')}\n`;
729:               break;
730:             case 'ScenarioChoice':
731:               modHeader = `${chalk.bold.yellow('🔀 [DECISION CROSSROADS] • A path diverges •')}\n`;
732:               break;
733:             case 'Embodied':
734:               modHeader = `${chalk.bold.green('💓 [SOMATIC SCAN] • Focus on body sensation •')}\n`;
735:               break;
736:             case 'Strategic':
737:               modHeader = `${chalk.bold.magenta('♟️ [TACTICAL WAR-TABLE] • Assess constraints •')}\n`;
738:               break;
739:             case 'SocialCooperative':
740:               modHeader = `${chalk.bold.cyan('🤝 [DIPLOMACY] • Navigating connection •')}\n`;
741:               break;
742:             case 'ImmersiveRPG':
743:               modHeader = `${chalk.bold.yellow('📖 [NARRATIVE SCENE] • The story unfolds •')}\n`;
744:               break;
745:             default:
746:               modHeader = `${chalk.bold.dim('[' + (mod as string).toUpperCase() + ']')}\n`;
747:           }
748: 
749:           console.log(`\n  ${modHeader}  ${chalk.magenta('[' + q.header + ']')}`);
750:           console.log(`  ${chalk.bold(q.question)}`);
751:           if (q.options?.length) {
752:             for (let i = 0; i < q.options.length; i++) {
753:               const opt = q.options[i];
754:               console.log(`    ${chalk.cyan('[' + (i + 1) + ']')} ${opt.label} — ${opt.description}`);
755:             }
756:           }
757:         }
758: 
759:         emitEvent('ask_user', {
760:           header: q.header,
761:           question: q.question,
762:           options: q.options?.map((o, i) => ({ index: i + 1, label: o.label, description: o.description })),
763:           allowWriteIn: q.allowWriteIn,
764:         });
765: 
766:         if (HEADLESS) {
767:           // Use forced responses pool if provided (one index per question, consumed sequentially)
768:           let selectedIdx: number;
769:           if (responsesPool && responsesPool.length > 0) {
770:             const forcedIdx = responsesPool.shift()!;
771:             if (q.options && forcedIdx >= 1 && forcedIdx <= q.options.length) {
772:               selectedIdx = forcedIdx - 1;
773:             } else {
774:               selectedIdx = 0;
775:             }
776:           } else {
777:             // Vary selection to probe different shadow patterns:
778:             // Cycle through options to ensure shadow detection has varied input
779:             const hash = (Date.now() + (q.options?.length ?? 4)) % 4;
780:             selectedIdx = hash < (q.options?.length ?? 4) ? hash : 0;
781:           }
782:           const selectedOpt = q.options?.[selectedIdx];
783:           const selectedLabel = selectedOpt?.label ?? '';
784: 
785:           // Shadow keyword injection for testing — randomly inject (10% chance)
786:           // to allow MOST encounters to pass and demonstrate altitude shifts.
787:           // When FORCE_SHADOW=none, skip injection entirely for clean progression.
788:           const shadowInjections = ['', 'i feel the need to withdraw from this confrontation', 'i must transcend these petty concerns and reach enlightenment', 'i prefer to stay here where it is safe and comfortable'];
789:           const injectShadow = FORCE_SHADOW !== 'none' && selectedIdx > 0 && Math.random() < 0.1;
790:           const writeInShadow = injectShadow ? (shadowInjections[selectedIdx] ?? '') : '';
791: 
792:           if (writeInShadow) {
793:             answers.push({ selectedLabels: [selectedLabel], writeInValue: writeInShadow });
794:           } else {
795:             answers.push({ selectedLabels: [selectedLabel] });
796:           }
797:         } else {
798:           const promptText = q.multiSelect
799:             ? '\n  Select (comma-separated): '
800:             : '\n  Select: ';
801:           const answer = await ask(promptText);
802:           const selections = answer.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
803:           const selectedLabels = selections
804:             .filter(n => n >= 1 && n <= (q.options?.length ?? 0))
805:             .map(n => q.options![n - 1]!.label);
806: 
807:           // Determine if input is a simple numeric choice from the options
808:           let isSimpleNumericChoice = false;
809:           if (q.options?.length && answer.trim()) {
810:             const parts = answer.split(',').map(s => s.trim());
811:             isSimpleNumericChoice = parts.every(part => {
812:               const num = parseInt(part, 10);
813:               return !isNaN(num) && String(num) === part && num >= 1 && num <= q.options!.length;
814:             });
815:           }
816: 
817:           if (q.allowWriteIn || (!q.options?.length && answer.trim())) {
818:             // Only populate writeInValue if it's NOT a simple numeric choice
819:             if (!isSimpleNumericChoice && answer.trim()) {
820:               answers.push({ selectedLabels, writeInValue: answer.trim() });
821:             } else {
822:               answers.push({ selectedLabels });
823:             }
824:           } else {
825:             answers.push({ selectedLabels });
826:           }
827:         }
828:       }
829: 
830:       return { answers };
831:     }
832:   };
833: 
834:   // Always route through AgenticOrchestrator — it handles LLM + fallback internally
835:   // Look up the assessment module from the registry to inject into the LLM context
836:   const baseModule = modRegistry?.get(encLine, encStage);
837: 
838:   // Build ConceptDraftIndex from the module registry so the LLM sees module metadata
839:   const conceptModules: Record<string, any> = {};
840:   if (modRegistry) {
841:     for (const m of modRegistry.getAll()) {
842:       const key = `${m.line.toLowerCase()}:${m.stage.toLowerCase()}`;
843:       conceptModules[key] = {
844:         line: m.line,
845:         stage: m.stage,
846:         title: `${m.line} ${m.stage} Module`,
847:         modalities: m.tasks.map(t => t.type === 'llm_dialogue' ? 'LanguageReflective' as const : 'Deterministic' as const),
848:       };
849:     }
850:   }
851: 
852:   const orchestrator = new AgenticOrchestrator({
853:     encounter: forcedEncounter,
854:     significator: sig,
855:     world,
856:     history,
857:     conceptIndex: { modules: conceptModules },
858:     uiHandler,
859:     module: modRegistry?.get(FORCE_LINE ?? encLine, FORCE_STAGE ?? encStage) ?? baseModule,
860:     noLlm: !LLM_ACTIVE,
861:     forceShadow: FORCE_SHADOW,
862:     consecutivePasses,
863:   });
864: 
865:   const outcome = await orchestrator.run();
866: 
867:   // Build a PlayerResponse from the orchestrator's consequence record
868:   const cr = outcome.consequenceRecord;
869:   const response: PlayerResponse = {
870:     encounterId: encounter.id,
871:     energeticDirection: cr.polarityTrace.energeticDirection,
872:     driveDirectionality: cr.polarityTrace.driveDirectionality,
873:     stageOrientation: cr.polarityTrace.stageOrientation,
874:     sourceOfNourishment: cr.polarityTrace.sourceOfNourishment,
875:     shadowSurfaced: cr.shadowSurfaced,
876:     shadowResolvedId: cr.shadowResolved,
877:     narrativeSummary: outcome.narrativeSummary,
878:   };
879: 
880:   return { outcome, response, narrativeSummary: outcome.narrativeSummary };
881: }
