931: // ── Single encounter mode ─────────────────────────────────────────────
932: async function runSingleEncounter(): Promise<void> {
933:   banner('CCRPG Single Encounter');
934: 
935:   bootRegistries();
936:   const moduleRegistry = bootModuleRegistry();
937:   (globalThis as any).__moduleRegistry = moduleRegistry;
938:   success(`${moduleRegistry.count()} modules loaded`);
939: 
940:   const sig = await createDefaultSignificator();
941:   const world = loadHolons();
942:   const session: SessionContext = {
943:     encountersSoFar: 0,
944:     sessionDurationMs: 0,
945:     targetSessionLength: 1,
946:     recentLines: [],
947:     ...(FORCE_LINE ? { forceLine: FORCE_LINE } : {}),
948:     ...(FORCE_STAGE ? { forceStage: FORCE_STAGE } : {}),
949:     ...(FORCE_MODALITY ? { forceModality: FORCE_MODALITY } : {}),
950:   } as any;
951:   const sessionState = startSession(sig, session);
952: 
953:   const now = Date.now();
954:   let { tickResult } = tickWithStrategy(sig, world, session, sessionState, null, null, now);
955: 
956:   // Create a local mutable copy of FORCE_RESPONSES for this session
957:   const responsesPool = FORCE_RESPONSES ? [...FORCE_RESPONSES] : undefined;
958: 
959:   // If forcing and no natural encounter, create a synthetic one
960:   if (!tickResult.encounter && (FORCE_LINE || FORCE_STAGE || FORCE_MODALITY)) {
961:     const synthLine = FORCE_LINE ?? 'Cognitive' as Line;
962:     const synthStage = FORCE_STAGE ?? 'Red' as Stage;
963:     const synthModality = FORCE_MODALITY ?? 'Deterministic' as Modality;
964:     const synthHolon = world.holons[0] ?? { id: 'synthetic', name: 'The Examiner', narrativeRole: 'guide' };
965:     const syntheticEncounter: ScheduledEncounter = {
966:       id: `synthetic:${synthLine}:${synthStage}:${now}`,
967:       moduleRef: `${synthLine}:${synthStage}`,
968:       modality: synthModality,
969:       targetLines: [synthLine],
970:       stage: synthStage,
971:       holonSource: synthHolon.id ?? 'synthetic',
972:       shadowTarget: null,
973:       polarityMode: 'Exploring',
974:       difficulty: 0.5,
975:       sessionPosition: 'peak',
976:       priority: 0.999,
977:       driveTarget: null,
978:       executionMode: 'capacity',
979:     };
980:     if (VERBOSE) warn(`No natural encounter at ${synthLine}:${synthStage} — using synthetic encounter`);
981:     tickResult = { ...tickResult, encounter: syntheticEncounter };
982:   }
983: 
984:   if (!tickResult.encounter) {
985:     error('No encounter available');
986:     return;
987:   }
988: 
989:   separator('Encounter');
990:   printEncounter(tickResult.encounter);
991: 
