// ── Setup wizard ──────────────────────────────────────────────────
async function runSetup(): Promise<void> {
  if (HEADLESS || JSON_MODE) { error('setup requires interactive mode (remove --headless and --json)'); return; }
  banner('CCRPG Setup Wizard');
  console.log(`\n  ${chalk.dim('This wizard configures CCRPG for your system.')}\n`);

  fs.mkdirSync(CONFIG_DIR, { recursive: true });
  fs.mkdirSync(path.join(CONFIG_DIR, 'saves'), { recursive: true });
  success(`Config directory: ${CONFIG_DIR}`);

  const existing = loadConfig();
  const currentKey = existing.llm?.apiKey ? `${existing.llm.apiKey.slice(0, 8)}...` : '(not set)';

  // API key input
  console.log(`\n  ${chalk.bold('LLM Configuration')}`);
  console.log(`  Current API key: ${chalk.dim(currentKey)}`);
  const newApiKey = await clackText({
    message: 'Enter API key (or press Enter to keep current):',
    defaultValue: '',
  });

  // Model selection via clack select
  const modelChoice = await select({
    message: 'Select your LLM model:',
    options: [
      { value: '1', label: 'gemma-4-31b-it', hint: 'Google, free tier' },
      { value: '2', label: 'gpt-4o-mini', hint: 'OpenAI' },
      { value: '3', label: 'claude-3-haiku', hint: 'Anthropic' },
      { value: '4', label: 'local', hint: 'Ollama / LM Studio' },
      { value: '5', label: 'Keep current', hint: existing.llm?.model ?? model },
    ],
  });

  let selectedModel = existing.llm?.model ?? model;
  let selectedBaseUrl = existing.llm?.baseUrl ?? baseUrl;
  if (typeof modelChoice === 'string') {
    switch (modelChoice) {
      case '1': selectedModel = 'gemma-4-31b-it'; selectedBaseUrl = 'https://generativelanguage.googleapis.com/v1beta/openai'; break;
      case '2': selectedModel = 'gpt-4o-mini'; selectedBaseUrl = 'https://api.openai.com/v1'; break;
      case '3': selectedModel = 'claude-3-haiku-20240307'; selectedBaseUrl = 'https://api.anthropic.com/v1'; break;
      case '4': selectedModel = 'local'; selectedBaseUrl = 'http://localhost:11434/v1'; break;
    }
  }

  // Default encounters
  const encStr = await clackText({
    message: `Default encounters per session [${existing.session?.defaultEncounters ?? 20}]:`,
    defaultValue: String(existing.session?.defaultEncounters ?? 20),
  });
  const defaultEncounters = parseInt(String(encStr)) || (existing.session?.defaultEncounters ?? 20);

  const config: CCRPGConfig = {
    llm: { apiKey: String(newApiKey).trim() || existing.llm?.apiKey, model: selectedModel, baseUrl: selectedBaseUrl },
    session: { defaultEncounters, defaultMode: existing.session?.defaultMode ?? 'full' },
  };

  saveConfig(config);
  success(`Configuration saved to ${CONFIG_FILE}`);
  console.log(`\n  Run ${chalk.bold('ccrpg')} to start your developmental journey.\n`);
}

// ── Status command ────────────────────────────────────────────────────
async function runStatus(): Promise<void> {
  banner('CCRPG Status');
  const config = loadConfig();
  console.log(`\n  ${chalk.bold('Configuration')}`);
  info('config', fs.existsSync(CONFIG_FILE) ? CONFIG_FILE : '(no config file)');
  info('model', config.llm?.model ?? model);
  info('api key', config.llm?.apiKey ? `${config.llm.apiKey.slice(0, 8)}...` : 'not set');

  bootRegistries();
  const moduleRegistry = bootModuleRegistry();
  (globalThis as any).__moduleRegistry = moduleRegistry;

  console.log(`\n  ${chalk.bold('Game State')}`);
  if (hasSave()) {
    const sig = loadSave();
    if (sig) {
      info('player', sig.id);
      info('stage', `${stageColor(sig.currentStage)(sig.currentStage)}`);
      info('encounters', String(sig.totalEncounters));
      info('sessions', String(sig.totalSessions));
      console.log(`\n  ${chalk.bold('Altitudes')}`);
      renderAltitudesChart(sig);
      console.log('');
      renderShadows(sig);
      renderDrives(sig);
    }
  } else {
    info('save', `${chalk.yellow('no saved game')} — run ${chalk.bold('ccrpg')} to start`);
  }

  console.log(`\n  ${chalk.bold('System')}`);
  info('modules', `${moduleRegistry.count()} loaded`);
  info('config dir', CONFIG_DIR);
  info('node', process.version);
  info('version', VERSION);
}

// ── Usage help ──────────────────────────────────────────────────────
function printHelp(): void {
  console.log(`\n${chalk.bold}${chalk.cyan}CCRPG${chalk.reset} v${VERSION} — Cognitive-Capacity-Driven RPG\n  Developmental Assessment Engine\n\n${chalk.bold}USAGE${chalk.reset}\n  ccrpg                        Start an interactive session\n  ccrpg session                Same as above\n  ccrpg setup                  Configure LLM and preferences\n  ccrpg diagnostic             Show system diagnostics\n  ccrpg status                 Show current developmental state\n  ccrpg new-game               Reset progress and start fresh\n\n${chalk.bold}SESSION OPTIONS${chalk.reset}\n  --encounters=N               Number of encounters (default: ${fileConfig.session?.defaultEncounters ?? 20})\n  --headless                   Run without user interaction\n  --json                       Machine-readable JSON output\n  --verbose                    Show full narrative and feedback\n  --no-llm                     Disable LLM, use module assessments only\n  --version                    Show version\n\n${chalk.bold}FORCED ENCOUNTERS (for testing)${chalk.reset}\n  --line=LINE                  Force a specific line\n  --stage=STAGE                Force a specific stage\n  --modality=MOD               Force a specific modality\n  --responses=1,2,3            Force specific option selections\n  --force-shadow=Q             Force a shadow quadrant\n\n${chalk.bold}CONFIGURATION${chalk.reset}\n  API key:   ~/.ccrpg/config.json or CCRPG_API_KEY env var\n  Model:     ~/.ccrpg/config.json or CCRPG_MODEL env var\n  Saves:     ~/.ccrpg/saves/\n\n${chalk.bold}EXAMPLES${chalk.reset}\n  ccrpg                                       # interactive session\n  ccrpg --headless --no-llm                   # quick automated test\n  ccrpg setup                                 # configure API key\n  ccrpg session --encounters=5 --json         # JSON event stream\n  ccrpg diagnostic                            # system diagnostics\n\n${chalk.bold}DEVELOPMENTAL SYSTEM${chalk.reset}\n  8 lines × 8 stages = 64 develop... (line truncated to 2000 chars)
}

// ── Main ──────────────────────────────────────────────────────────────
async function main(): Promise<void> {
  // ponytail: --version and --help handled by commander automatically
  if (subcommand === 'setup') { await runSetup(); return; }
  if (subcommand === 'status') { await runStatus(); return; }
  if (subcommand === 'new-game') { deleteSave(); deleteWorldSave(); console.log(`${chalk.yellow('↻')} Progress reset. Run ${chalk.bold('ccrpg')} to start a new game.`); return; }

  if (!JSON_MODE) {
    console.log(`\n${chalk.bold.cyan('CCRPG')} v${VERSION}`);
    console.log(`${chalk.dim('Cognitive-Capacity-Driven RPG — Developmental Assessment Engine')}`);
  }

  try {
    const effectiveMode: string = subcommand === 'diagnostic' ? 'diagnostic' : subcommand === 'session' ? 'full' : 'full';
    switch (effectiveMode) {
      case 'diagnostic': await runDiagnostic(); break;
      case 'encounter': await runSingleEncounter(); break;
      case 'session': case 'full': default: await runFullSession(); break;
    }
  } catch (err: any) {
    error(`Fatal: ${err.message || err}`);
    if (!JSON_MODE) console.error(err.stack);
    emitEvent('fatal', { error: err.message, stack: err.stack });
  } finally {
    // cleanup if needed
  }
}

