56: /**
57:  * Build an LLM prompt for a Language-Reflective encounter.
58:  */
59: export function buildPrompt(
60:   frequencySpec: FrequencySpec,
61:   encounterContext: { readonly line: Line; readonly stage: Stage; readonly purpose: string },
62: ): string {
63:   const tone = frequencySpec.toneDirective;
64:   const vocab = frequencySpec.vocabularyBand;
65:   const taboos = frequencySpec.taboos.join(', ');
66:   const lens = frequencySpec.valueLens;
67: 
68:   return [
69:     `[REFLECTIVE PROMPT GENERATION]`,
70:     `Tone: ${tone}`,
71:     `Vocabulary: ${vocab}`,
72:     `Value lens: ${lens}`,
73:     `Avoid: ${taboos}`,
74:     `Line: ${encounterContext.line}`,
75:     `Purpose: ${encounterContext.purpose}`,
76:     `Generate a single reflective prompt (max 80 words) that invites the player to name or explain`,
77:     `an experience through the value lens above. Do not list, instruct, or evaluate.`,
78:     `Output JSON: { "prompt": string, "follow_ups": string[], "scoring_anchors": string[] }`,
79:   ].join('\n');
80: }
81: 
82: /**
83:  * Score a player's response against the rubric (local heuristic, no LLM call).
84:  * Returns a score 0-1 and signal strings.
85:  * Stage-aware calibration: early stages have lower length expectations and reward
86:  * concrete language; middle stages expect structured reasoning; later stages expect
87:  * depth and reward nuance/paradox.
88:  */
89: export function scoreResponse(
90:   response: string,
91:   stage: Stage,
92: ): { readonly score: number; readonly signals: readonly string[] } {
93:   const signals: string[] = [];
94:   const words = response.trim().split(/\s+/).filter((w) => w.length > 0);
95:   const wordCount = words.length;
96: 
97:   // Stage-aware thresholds
98:   const earlyStages: readonly Stage[] = ['Infrared', 'Magenta', 'Red'];
99:   const middleStages: readonly Stage[] = ['Amber', 'Orange'];
100:   // Later stages: Green, Turquoise, White
101: 
102:   const isEarly = earlyStages.includes(stage);
103:   const isMiddle = middleStages.includes(stage);
104:   // isLater is the default (Green, Turquoise, White)
105: 
106:   // Self-referential language detection
107:   const selfRefPattern = /\b(I|my|me|myself|I'm|I've|I'd|I'll)\b/gi;
108:   const selfRefMatches = response.match(selfRefPattern) ?? [];
109:   const selfRefRatio = wordCount > 0 ? selfRefMatches.length / wordCount : 0;
110: 
111:   // Concrete vs abstract heuristic (concrete words tend to be shorter, more common)
112:   const concreteWords = words.filter((w) => w.length <= 6);
113:   const concreteRatio = wordCount > 0 ? concreteWords.length / wordCount : 0;
114: 
115:   // Nuance/paradox indicators (relevant for later stages)
116:   const nuancePattern = /\b(both|yet|paradox|complex|nuance|perhaps|tension|simultaneously|ambig)/gi;
117:   const nuanceMatches = response.match(nuancePattern) ?? [];
118: 
119:   // Length adequacy - calibrated by stage
120:   let lengthScore = 0;
121:   if (isEarly) {
122:     // Early stages: 5+ words is acceptable, sweet spot 5-60
123:     if (wordCount >= 5 && wordCount <= 60) {
124:       lengthScore = 1.0;
125:     } else if (wordCount >= 3 && wordCount < 5) {
126:       lengthScore = wordCount / 5;
127:     } else if (wordCount > 60) {
128:       lengthScore = 0.85;
129:     } else {
130:       lengthScore = wordCount / 5 * 0.3;
131:     }
132:   } else if (isMiddle) {
133:     // Middle stages: 15+ words expected, sweet spot 15-80
134:     if (wordCount >= 15 && wordCount <= 80) {
135:       lengthScore = 1.0;
136:     } else if (wordCount >= 5 && wordCount < 15) {
137:       lengthScore = wordCount / 15;
138:     } else if (wordCount > 80) {
139:       lengthScore = 0.8;
140:     } else {
141:       lengthScore = wordCount / 5 * 0.3;
142:     }
143:   } else {
144:     // Later stages: 20+ words expected, sweet spot 20-100
145:     if (wordCount >= 20 && wordCount <= 100) {
146:       lengthScore = 1.0;
147:     } else if (wordCount >= 8 && wordCount < 20) {
148:       lengthScore = wordCount / 20;
149:     } else if (wordCount > 100) {
150:       lengthScore = 0.8;
151:     } else {
152:       lengthScore = wordCount / 8 * 0.2;
153:     }
154:   }
155: 
156:   // Depth: longer, more developed responses score higher
157:   const depthScore = Math.min(1.0, wordCount / 30);
158: 
159:   // Coherence: presence of connective words
160:   const connectivePattern = /\b(because|since|therefore|so|but|although|however|when|after|before)\b/gi;
161:   const connectives = response.match(connectivePattern) ?? [];
162:   const coherenceScore = Math.min(1.0, connectives.length * 0.3 + 0.2);
163: 
164:   // Self-reference score
165:   const selfRefScore = Math.min(1.0, selfRefRatio * 5);
166: 
167:   // Stage indicators - calibrated by stage tier
168:   let stageIndicatorScore: number;
169:   if (isEarly) {
170:     // Early stages reward concrete language
171:     stageIndicatorScore = concreteRatio > 0.4 ? 0.7 : concreteRatio > 0.3 ? 0.5 : 0.3;
172:   } else if (isMiddle) {
173:     // Middle stages reward structured reasoning (connectives as proxy)
174:     stageIndicatorScore = connectives.length >= 2 ? 0.7 : connectives.length >= 1 ? 0.5 : 0.3;
175:   } else {
176:     // Later stages reward nuance/paradox
177:     stageIndicatorScore = nuanceMatches.length >= 2 ? 0.8 : nuanceMatches.length >= 1 ? 0.6 : 0.3;
178:   }
179: 
180:   // Drive signals
181:   const driveScore = selfRefMatches.length > 0 ? 0.4 : 0.1;
182: 
183:   // Weighted sum per rubric
184:   const score =
185:     depthScore * 0.3 +
186:     coherenceScore * 0.2 +
187:     selfRefScore * 0.2 +
188:     stageIndicatorScore * 0.2 +
189:     driveScore * 0.1;
190: 
191:   const finalScore = Math.min(1.0, Math.max(0, score * lengthScore + (1 - lengthScore) * score * 0.3));
192: 
193:   // Collect signals
194:   if (selfRefMatches.length > 0) {
195:     signals.push('self-referential language detected');
196:   }
197:   if (connectives.length > 0) {
198:     signals.push('causal reasoning present');
199:   }
200:   if (wordCount < 5) {
201:     signals.push('minimal response');
202:   }
203:   if (wordCount >= 30) {
204:     signals.push('substantial elaboration');
205:   }
206:   if (depthScore > 0.7) {
207:     signals.push('depth indicator');
208:   }
209:   if (nuanceMatches.length > 0 && !isEarly) {
210:     signals.push('nuance/paradox language detected');
211:   }
212: 
213:   return { score: Math.round(finalScore * 1000) / 1000, signals };
214: }

